// Find.cpp : implementation file//#include "stdafx.h"#include "FBDsConverter.h"#include "FBDsConverterDoc.h"#include "Find.h"#include <rsuPaths.h>#ifdef _DEBUG#define new DEBUG_NEW#undef THIS_FILEstatic char THIS_FILE[] = __FILE__;#endif// KFind dialogusing namespace std;IMPLEMENT_DYNAMIC(KFind, CDialog)KFind::KFind(CWnd* pParent /*=NULL*/)	: CDialog(KFind::IDD, pParent){}KFind::~KFind(){}void KFind::DoDataExchange(CDataExchange* pDX){  CDialog::DoDataExchange(pDX);  DDX_Control(pDX, IDC_LIST1, List);  DDX_Control(pDX, IDC_MASK, Mask);}BEGIN_MESSAGE_MAP(KFind, CDialog)  ON_BN_CLICKED(IDC_FIND, &KFind::OnBnClickedFind)  ON_NOTIFY(NM_DBLCLK, IDC_LIST1, &KFind::OnNMDblclkList1)  ON_WM_DESTROY()  ON_WM_CLOSE()END_MESSAGE_MAP()// KFind message handlersBOOL KFind::OnInitDialog(){  CDialog::OnInitDialog();  CRect rc;  List.GetClientRect( &rc );  int w = rc.right - GetSystemMetrics( SM_CXVSCROLL ) - 2;  List.InsertColumn ( 0, "", LVCFMT_LEFT, w/2 );  List.InsertColumn ( 1, "", LVCFMT_LEFT, w/2 );  List.SetExtendedStyle ( LVS_EX_FULLROWSELECT|LVS_EX_GRIDLINES );  ReadStr();  return TRUE;  // return TRUE unless you set the focus to a control  // EXCEPTION: OCX Property Pages should return FALSE}void ToUpper( char * pLine ){  while( *pLine )  {    *pLine = toupper( *pLine );    pLine++;  }}void KFind::OnBnClickedFind(){  UpdateData();  List.DeleteAllItems();  m_Sheets.clear();  char ObjTxtFiltr[256] = { 0 };  Mask.GetWindowText( ObjTxtFiltr, 255 );  int Ind = (int)Mask.SendMessage( CB_FINDSTRINGEXACT, -1, (LPARAM)ObjTxtFiltr );  if ( Ind != CB_ERR )    Mask.SendMessage( CB_DELETESTRING, Ind, 0 );    COMBOBOXEXITEM Item;  memset ( &Item, 0, sizeof ( Item ));  Item.pszText = ObjTxtFiltr;  Item.mask = CBEIF_TEXT;  Mask.SendMessage( CBEM_INSERTITEM, 0, (LPARAM)&Item );  SaveStr();  ToUpper( ObjTxtFiltr );  Find( ObjTxtFiltr );}#define MASK_FILE_NAME "%sFind_hcd.txt"void KFind::SaveStr(){  int K = (int)Mask.SendMessage( CB_GETCOUNT, 0, 0 );   char Path[_MAX_PATH];  sprintf_s ( Path, _MAX_PATH-1, MASK_FILE_NAME, rsuGetMemoryPath());  FILE * F; fopen_s ( &F, Path, "wt" );  if ( F == NULL )    return ;  for ( int n = K-1; n >= 0; n-- )  {    Mask.SendMessage( CB_GETLBTEXT, n, (LPARAM)Path );    fprintf ( F, "%s\n", Path );  }  fclose ( F );}void KFind::ReadStr(){  char Path[_MAX_PATH];  sprintf_s ( Path, _MAX_PATH-1, MASK_FILE_NAME, rsuGetMemoryPath());  FILE * F; fopen_s ( &F, Path, "rt" );  if ( F == NULL )    return ;  while ( fgets ( Path, 1023, F ))  {    int L = (int)strlen ( Path );    if ( L < 2 )      continue;    Path[L-1] = 0;    COMBOBOXEXITEM Item;    memset ( &Item, 0, sizeof ( Item ));    Item.pszText = Path;    Item.mask = CBEIF_TEXT;    Mask.SendMessage( CBEM_INSERTITEM, 0, (LPARAM)&Item );  }  fclose ( F );}extern CFBDsConverterDoc* g_Doc;void KFind::OnNMDblclkList1(NMHDR *pNMHDR, LRESULT *pResult){  *pResult = 0;  int selectIdx = List.GetNextItem( -1, LVNI_SELECTED );  if ( selectIdx < 0 )    return;  if( m_Sheets.size()<selectIdx )    return;  string name = m_Sheets.at(selectIdx);  g_Doc->OpenEmf( name.c_str() );}bool CompName( int lN, const char * Name, int lS, const char * S ){  if ( lN == 0 && lS == 0 )    return true;  if ( lS == 1 && S[0] == '*' )    return true;  if ( lN > 0 && lS == 0 )    return false;  if ( S[0] == '*' )  {    for ( int n = 0; n < lN; n++ )    {      if ( CompName ( lN - n, Name + n, lS - 1, S + 1 ))        return true;    }    return false;  }  if ( S[0] == '?' )  {    return CompName ( lN - 1, Name + 1, lS - 1, S + 1 );  }  if ( S[0] != Name[0] )    return false;  return CompName ( lN - 1, Name + 1, lS - 1, S + 1 );}bool FiltrName( const char * Filtr, const char *Name ){  int lN = lstrlen ( Name );  bool Res = false;  const char * P = Filtr;  while( 1 )  {    char * Pn = (char*)strchr( P, ';' );    if ( Pn )      *Pn = 0;    if ( CompName ( lN, Name, lstrlen( P ), P ) )    {      if ( Pn )        *Pn = ';';      Res = true;      break;    }    if ( Pn )    {      *Pn = ';';      P = Pn + 1;    }    else      break;  }  return Res;}void KFind::Find( LPCSTR lpszMask ){  int c = 0;  for( tMapVectString_::iterator it=theApp.m_ObjOnSheets.begin(), end( theApp.m_ObjOnSheets.end() ); it!=end; ++it )  {    string obj = it->first;    if( FiltrName( lpszMask, obj.c_str()) )    {      for( tMapVectString_::mapped_type::iterator it2=it->second.begin(), end2( it->second.end()); it2!=end2; ++it2 )      {        m_Sheets.push_back( (*it2) );        for( tSheetInfo_::iterator it3=theApp.m_SheetTree.begin(), end3(theApp.m_SheetTree.end()); it3!=end3; ++it3 )        {          if( !m_Sheets.back().compare( it3->szFile ) )          {            int N = List.InsertItem( c, it3->szSheet.c_str() );            List.SetItemText( N, 1, it3->szPage.c_str() );            c++;          }        }      }    }  }}void KFind::OnDestroy(){  CDialog::OnDestroy();  delete this;}void KFind::OnClose(){  CDialog::OnClose();  DestroyWindow();}